\label{lem:causaltriple10}
Пусть $c=1+\sigma3^g+3^hV$, $h=g+\delta$,
$\sigma\in\{-1,1\}$, $V\in\Z_3^\times$ и $g,\delta\ge q$.
Пусть $X,Y=cX+d$ имеют первые $L$ цифр в $\{0,1\}$.
Для окон длины $q$ со стартами $j,j+\delta,j+h$,
при $j\ge0$ и $j+h+q\le L$, обозначенных $A,B,C$,
существует центр $D_j$, зависящий только
от $X_{<j}$, такой, что
\begin{equation}\label{eq:causaltriple10}
VA+\sigma B+C+D_j+e\in\Sig_q\pmod{3^q}
\quad\text{при некотором }e\in\{0,\sigma\}.
\end{equation}

\label{lem:fiber10}
Пусть $q\ge2$, $A,B,C\subseteq\Sig_q$ непусты,
$V\in\Z_3^\times$, $D\in\Z_3$, $\sigma\in\{-1,1\}$.
Для каждой тройки $a,b,c$ из полного
$A\times B\times C$ пусть существует $e\in\{0,\sigma\}$,
для которого $Va+\sigma b+c+D+e\in\Sig_q$.
Тогда для каждой тройки непустых младших слоёв
\begin{equation}\label{eq:fiber10}
\frac{\log|A_u|}{\ell}+|\var(B_v)|+|\var(C_w)|\le q-1.
\end{equation}

\label{thm:hyper10}
Для целых $T_1,T_2\ge1$ положим
\[
\theta=Q\left(\frac{T_2+1}{T_1}+\frac1{T_2}\right)\le\frac12.
\]
Каждому слову можно детерминированно назначить отпечаток
$\mathcal F$ из не более $\theta N$ записей вида $(i,X_i)$
и непустые алфавиты $A_i$, измеримые относительно
$(X_{<i},\mathcal F)$ и содержащие фактические условные поддержки.
На каждом пути все, кроме не более
\begin{equation}\label{eq:bad10}
E_{\rm bad}\le Q(T_1+T_2)N
\end{equation}
гиперрёбер, удовлетворяют полной совместимости
$A_i\times A_{i+\delta_s}\times A_{i+h_s}
\subseteq\mathcal R_{i,s}(X_{<i})$.
При любом распределении на $\mathcal W$
\begin{equation}\label{eq:fingerprint10}
\ent(\mathcal F)\le N[\mathfrak h(\theta)+\theta\log Q].
\end{equation}

\label{lem:exact}
Для фиксированных единиц $\rho,a_1,\ldots,a_k\in\Z_3^\times$
уравнение
\begin{equation}\label{eq:ess}
\rho^{-1}4^n-\sum_{t=1}^{k}a_t3^{e_t}=1,
\qquad 0<e_1<\cdots<e_k
\end{equation}
имеет лишь конечное число решений с различными
неотрицательными целыми $n$.

\label{lem:tails}
Для каждого фиксированного $r\ge3$ можно извлечь
подпоследовательность, единицы $a_1,\ldots,a_{r-2}\in\Z_3^\times$
и показатели $0<e_{1i}<\cdots<e_{r-1,i}=E_i$, такие, что
\begin{equation}\label{eq:tails}
c_i^*=1+\sum_{t=1}^{r-2}a_t3^{e_{ti}}+u_i^*3^{E_i},
\qquad u_i^*\in\Z_3^\times.
\end{equation}
Все $r-1$ соседних промежутков стремятся к бесконечности.
Дополнительно можно обеспечить
\begin{equation}\label{eq:separation}
\min_{1\le t\le r-1}(e_{t,i+1}-e_{t-1,i+1})>E_i,
\qquad e_{0i}=0.
\end{equation}

\label{thm:container}
Для положительных целых порогов
$T_{\rm s},T_2,\ldots,T_{r-1}$ положим
\begin{equation}\label{eq:theta}
\theta=Q\left[
\frac{D\sum_{j=2}^{r-1}T_j+1}{T_{\rm s}}
+\frac1{T_2}
+D\sum_{j=3}^{r-1}\frac{1+\sum_{l=2}^{j-1}T_l}{T_j}
\right]\le\frac12.
\end{equation}
Каждому слову назначаются отпечаток $\mathcal F$
из не более $\theta N$ пар $(i,Z_i)$ и непустые
алфавиты $A_i$, определяемые $(x_{<i},\mathcal F)$
и содержащие фактическую букву.
Кроме не более
\begin{equation}\label{eq:bad}
E_{\rm bad}\le
Q\left(T_{\rm s}+D\sum_{j=2}^{r-1}T_j\right)N
\end{equation}
рёбер на каждом слове, выполняется
$\prod_\nu A_{i_\nu}\subseteq\mathcal R_e(x_{<i_0})$.
Для любого распределения на $\mathcal W$
\begin{equation}\label{eq:fentropy}
\HH(\mathcal F)\le N[\mathfrak h(\theta)+\theta\log Q],
\quad \mathfrak h(x)=-x\log x-(1-x)\log(1-x).
\end{equation}

\label{lem:tails}
Для каждого фиксированного $r\ge3$ можно извлечь
подпоследовательность и единицы
$a_1,\ldots,a_{r-2}\in\Z_p^\times$, такие, что
\begin{equation}\label{eq:tails}
c_i^*=1+\sum_{t=1}^{r-2}a_tp^{e_{ti}}+u_i^*p^{E_i},
\qquad u_i^*\in\Z_p^\times.
\end{equation}
Здесь $0=e_{0i}<e_{1i}<\cdots<e_{r-1,i}=E_i$,
все соседние промежутки стремятся к бесконечности
и, после дальнейшего извлечения,
\begin{equation}\label{eq:separation}
\min_t(e_{t,i+1}-e_{t-1,i+1})>E_i.
\end{equation}

\label{lem:causal}
Пусть $X,Z_i=c_iX+d_i$ имеют первые $L$ цифр в $\{0,1\}$.
Для $j\ge0$, $j+E_i+q\le L$ возьмём первое и последнее
$X$-окна $B_0,B_{\rm end}$, а в позиции $j+E_i-e_{ti}$
возьмём окно $B_t$ ряда $Y_t$.
Тогда modulo $p^q$
\begin{equation}\label{eq:causal}
u_iB_0+\sum_{t=1}^{r-2}B_t+B_{\rm end}+D_j+e
\in\Sigma_{p,q}
\quad\text{для некоторого }e\in\{0,\ldots,r-2\},
\end{equation}
где $D_j$ зависит только от $X_{<j}$ и фиксированной системы.

