\label{lem:gap}
$G$ состоит в точности из $3$-адических записей, у которых
между соседними единицами не меньше пяти нулей.

\label{thm:second}
\[
\boxed{C(1,4,256,4^{1+3^k})=\{0\}\quad(k\ge0,\ k\ne1).}
\]
При $k=1$ множитель равен $256$, поэтому пересечение равно $G$.

\label{thm:third}
\[
\boxed{C(1,4,256,4^{4+3^k})=\{0\}\quad\text{для всех }k\ge0.}
\]

\label{lem:cosets}
В $\Z/p^k\Z$ пересечение любого класса по подгруппе порядка $p^h$
с любым сдвигом $z+Y_k$ содержит не больше $N_h$ элементов.

[Ёмкость блока]\label{lem:capacity}
Пусть непустые $A_1,\ldots,A_r\subseteq\Z/p^k\Z$ удовлетворяют
\[
 T=A_1+\cdots+A_r\subseteq(z_1+Y_k)\cup(z_2+Y_k).
\]
Тогда
\begin{equation}\label{eq:capacity}
 \sum_{i=1}^r\log|A_i|\le rh_0\log p+2N_k\log2=:B_{r,k}.
\end{equation}

[Точная классификация вложений]\label{thm:rigidity}
Для $a,d\in\Z_3$, $d\ne0$, включение $a+dH_B\subseteq\Sig$
равносильно следующим двум условиям:
\begin{enumerate}
\item $d=\sum_{r\in J}\sigma_r3^{b_r}$ имеет конечную сбалансированную
запись, $\sigma_r\in\{-1,1\}$, а показатели $b_r$ попарно различны
по модулю $B$;
\item $a\in\Sig$, и для всех $r$ и $k\ge0$ его цифра в позиции
$b_r+Bk$ равна $(1-\sigma_r)/2$.
\end{enumerate}
В частности, $d\in\Z$ и его сбалансированный вес не больше $B$.

\label{lem:measure}
Если сбалансированный носитель $2^nd$ содержит два показателя,
сравнимых по модулю $B$, то $A_n$ нигде не плотно и имеет меру нуль.

[Конечность малого сбалансированного веса]\label{lem:weight}
Для каждого $D\in\Z\setminus\{0\}$ и $B\ge1$ число показателей
$n\ge0$ со сбалансированным весом $w_{\rm bal}(2^nD)\le B$ не больше
\begin{equation}\label{eq:FB}
 F(B)=2+\sum_{t=2}^B2^t\exp\bigl((6t)^{3t}(t+2)\bigr).
\end{equation}

\label{cor:finite-state}
Если компакт $P\subseteq E_2$ задаётся конечным графом с цифровыми
метками, то $P$ счётен и все его точки рациональны в $\Q_3$.

\label{lem:g6}
$G$ состоит в точности из записей, в которых расстояние между любыми
двумя последовательными единицами не меньше шести.

[Прямой зазор, включая сдвинутую цель]\label{thm:ggap}
Для каждого $n>8$ и каждого $a\in\Z_3$ множество
$F_{a,n}=\{x\in G:a+2^nx\in\Sigma\}$ удовлетворяет
\begin{equation}\label{eq:ggap}
 h(F_{a,n})\le\log\lambda+\frac1{L(n)}
                    \log(1-\lambda^{-L(n)})<\log\lambda.
\end{equation}
Поэтому правая часть, делённая на $\log3$, ограничивает сверху
$\dimB F_{a,n}$ и $\dimH F_{a,n}$.

[Точное множество плато для $G$]\label{cor:gplateau}
\[
 \boxed{\ h(G\cap2^{-n}\Sigma)=h(G)
          \quad\Longleftrightarrow\quad n\in\{0,2,8\}.\ }
\]

[Запрет разностей носителя]\label{thm:returnsupport}
Если добавление $M^{-1}\Sigma$ сохраняет энтропию над $K$, то
\begin{equation}\label{eq:supportdiff}
 \bigl(\sbal(M\Delta)-\sbal(M\Delta)\bigr)
                      \cap(B+\mathcal R_v)=\varnothing.
\end{equation}
Если $M=2^n$ и $K$ апериодична, то
\begin{equation}\label{eq:apcutoff}
 n<8s^2-8s+4.
\end{equation}

[Явная граница показателя при ограниченном весе]\label{thm:weight}
Пусть $D\in\Z\setminus\{0\}$, $B\ge1$,
$D_0=|D|/3^{v_3(D)}$, $H=2+\operatorname{bitlength}(D_0)$.
Тогда
\begin{equation}\label{eq:weightcutoff}
 \wbal(2^nD)\le B\quad\Longrightarrow\quad
 n<(10^{15}BH)^{2B}.
\end{equation}

[Граница через число состояний]\label{thm:graphcutoff}
Пусть $C$ задаётся достижимым существенным carry-графом с не более чем
$S$ состояниями и $h(C)>0$. Тогда
\begin{equation}\label{eq:graphcutoff}
 n\ge(10^{17}S^2)^{4S}
 \quad\Longrightarrow\quad h(C\cap2^{-n}\Sigma)<h(C).
\end{equation}
Все показатели, сохраняющие энтропию, образуют эффективно вычислимое
конечное множество.

[Точный подсчёт]\label{lem:badcount}
Множество $\mathcal E_K(R)$ периодично modulo $2\cdot3^{R-1}$
и имеет точную плотность
\begin{equation}\label{eq:rho}
 \rho_K(R)=3^{d(b-1)-R+1}
            \prod_{r=1}^{d-1}(2\ell_r-2b+3)
       =O_K(R^{d-1}3^{-R})\longrightarrow0.
\end{equation}
При $d=1$ пустое произведение равно $1$, и $\rho_K(R)=3^{b-R}$.

[Общий закон для фиксированного $C$]\label{cor:globaldensity}
Пусть $C=C(1,M_1,\ldots,M_t)$ фиксировано и $h(C)>0$.
Для каждого $\eta>0$ эффективно находятся $\epsilon_C(\eta)>0$
и явное периодическое множество $\mathcal E$ плотности не больше $\eta$,
такие что
\begin{equation}\label{eq:generaldensity}
 n\notin\mathcal E\quad\Longrightarrow\quad
 h(C\cap2^{-n}\Sigma)\le h(C)-\epsilon_C(\eta).
\end{equation}
В частности,
\begin{equation}\label{eq:gaplimit}
 \lim_{\epsilon\downarrow0}\overline{\operatorname{dens}}
 \{n:h(C)-h(C\cap2^{-n}\Sigma)<\epsilon\}=0.
\end{equation}

[Степенная оценка плотности]\label{cor:powerrate}
Пусть $h(C)>0$, а $d_*$ --- наибольший период максимальной компоненты $C$,
$\alpha=\log3/h(C)$. Тогда при $\epsilon\downarrow0$
\begin{equation}\label{eq:powerrate}
 \overline{\operatorname{dens}}
 \{n:h(C)-h(C\cap2^{-n}\Sigma)<\epsilon\}
 =O_C\!\left(\epsilon^\alpha
       (\log(1/\epsilon))^{d_*-1+\alpha}\right).
\end{equation}
Константы в этой верхней оценке эффективно определяются старым графом.

[Полный аддитивный слой]\label{lem:fibre}
Если $p$ --- простой, $p^2\mid q$ и
$\ord_q(3)=p\ord_{q/p}(3)$, то $A_q=\varnothing$.

[Конечность допустимых знаменателей]\label{thm:denom}
Если несократимая точка $a/q\in\Sigma$ имеет все простые делители
знаменателя в $S$, то
\begin{equation}\label{eq:denom}
 \boxed{\ \ord_q(3)\mid T_S,\qquad q\mid M_S\mid3^{T_S}-1.\ }
\end{equation}
При $q=1$ используется соглашение $\ord_1(3)=1$.

[Равномерная оценка при запрещённом нечётном знаменателе]\label{cor:finiteq}
Пусть $q>1$ нечётно, $3\nmid q$, $A_q=\varnothing$,
$h=v_2(\ord_q3)$ и $H_q=2+\max(1,h)$.
Для несократимой точки $x=a/(2^s q)$ все возвраты лежат в интервале
\begin{equation}\label{eq:qinterval}
 \max(0,s-H_q)\le n\le s-2,
 \qquad \#R(x)\le\lfloor H_q/2\rfloor.
\end{equation}

\label{lem:digitwise}
Пусть $x,y\in\Sig$. Тогда
(а) уравновешенные цифры $x-y$ равны $x_j-y_j$;
(б) обычные цифры $x+y$ равны $x_j+y_j$ (переносов нет).

\label{lem:elementary}
\begin{itemize}
\item[(а)] Если $N\equiv2\pmod3$, то $C(1,N)=\{0\}$.
\item[(б)] $C(1,3N_1,N_2,\dots)=C(1,N_1,N_2,\dots)$ и $C(1,3^k)=\Sig$.
\item[(в)] $x\in\Sig\iff3x\in\Sig$; поэтому $F(3^kN)=F(N)$.
\end{itemize}

[нулевая размерность и рациональность; \st{Д}]\label{lem:zero}
В условиях предложения~\ref{prop:dim} равносильны: (а) $\dimH X=0$;
(б) каждая достижимая живая КСС --- либо одно состояние без петли, либо один простой
ориентированный цикл. При этом все точки $X$ рациональны, а $X$ счётно. Кроме того,
$\dimH X>0$ тогда и только тогда, когда через некоторое достижимое живое состояние проходят
два различных простых цикла.

[A; \st{Д, Н}]\label{thm:reduction}
Пусть $\lambda\in\E\setminus\{0\}$ и $S(\lambda)=\{s_1<s_2<\dots\}$. Тогда
\begin{enumerate}
\item все разности $s_i-s_j$ чётны;
\item нет $n$ с $n,n+2,n+4\in S(\lambda)$;
\item $s_{i+2}-s_i\ge4$ для всех $i$. В частности, $(s_1,s_3,s_5)$ --- три события с
чётными промежутками $\ge4$.
\end{enumerate}
Следовательно,
\begin{equation}\label{eq:reduction}
\E\subseteq\{0\}\cup\bigcup_{h\ge0}\ \bigcup_{\substack{a,c\ge4\\ \text{чётные}}}2^{-h}C(1,2^a,2^{a+c}),
\qquad
\dimH\E\le\sup_{a,c\ge4\ \text{чётные}}\dimH C(1,2^a,2^{a+c}).
\end{equation}

[неравенство бывает строгим; \st{ДК, Н}]\label{prop:strict}
При нечётном $g$ имеем $C(1,2^g)=\{0\}$, но $\dimH C_\mathbb R(2^g)>0$ при $g=5,7,9,11,13$.
Значения $0.1590$, $0.2559$, $0.2367$, $0.2780$, $0.2504$ (\st{Ч}).

[переворот; \st{Д}]\label{lem:flip}
В свободной позиции два чтения $e=0,1$ дают разные $\beta$: значения $T$ отличаются на
$m\not\equiv0\pmod3$.

[явный вид; \st{Д}]\label{lem:lossfree}
Свободное состояние $(c,w)$ без потерь $\iff c\not\equiv m\pmod3$. Вынужденное состояние с
вынужденной цифрой $e$ без потерь $\iff me+c\equiv0\pmod3$, то есть $\beta=0$.

[C, критерий равенства; \st{Д, Н}]\label{thm:criterion}
Пусть $N\in\Z$. Тогда $\dimH X(N,C)=\lth$ в том и только том случае, когда из состояния,
отвечающего $C$, достижима плотная КСС.

[D, жёсткость; \st{Д, Н}]\label{thm:rigidity}
Пусть $N\in\Z$, $N\equiv1\pmod3$, $N\ne1$, $N-1=3^am$, $3\nmid m$. Равносильны:
\begin{enumerate}
\item $F(N)=\lth$;
\item $\sup_{C\in\Z}\dimH X(N,C)=\lth$;
\item в $R(N)$ есть плотная КСС;
\item $m=1$ или $m=3^a-1$, то есть $N=3^a+1$ или $N=3^{2a}-3^a+1$.
\end{enumerate}

[флаги; \st{Д}]\label{lem:flags}
В каждом состоянии $(c,w)\in Q$ либо $c\equiv0$, либо $c\equiv-\mu\pmod3$. Положим
\emph{флаг} $f=0$ в первом случае и $f=1$ во втором. Тогда:
\begin{enumerate}
\item на каждом ребре из состояния с флагом $f$, читающем $e$, выход равен $\beta=\mu(e-f)$;
\item для каждого пути из $s=(c,w)\in Q$, читающего $\lambda$, с флагами $f_j$ и
$\mathbf F=\sum_jf_j3^j$ выполнены равенства
\[
\mathbf F=M\lambda-\mu c\in\Sig,\qquad m\lambda+c=\mu g,\qquad\text{где } g:=\lambda-\mathbf F,
\]
причём уравновешенные цифры $g$ равны $g_j=\lambda_j-f_j=\mu\beta_j$;
\item (плотность) в свободной позиции оба чтения ведут в $Q$; в вынужденной позиции
вынужденная цифра равна флагу, то есть $g_j=0$.
\end{enumerate}

[полностью свободное состояние и отклонения; \st{Д}]\label{lem:deviation}
В $Q$ есть состояние $s^*=(c^*,0^a)$. Из него выходят пути:
\begin{itemize}
\item $P_\emptyset$: всюду читаем $\lambda_k=f_k$. Тогда $g=0$, и все позиции свободны;
\item $P_j$ ($j\ge0$): читаем $\lambda_j=1-f_j$, а во всех остальных позициях --- флаг.
Тогда $g=\varepsilon3^j$, $\varepsilon=1-2f_j$, и единственная вынужденная позиция --- $j+a$.
\end{itemize}
Аналогичный путь с отклонениями во всех позициях множества $J$ существует, если
$J\cap(J+a)=\emptyset$.

[\st{Д, Н}]\label{cor:full-top}
Для натурального $N$, не являющегося степенью тройки, $F(N)\le\lth$, и равенство выполняется
тогда и только тогда, когда $N=3^k(3^a+1)$ или $N=3^k(3^{2a}-3^a+1)$, где $a\ge1$, $k\ge0$.

[\st{Д}; семейство $3^k+1$ известно~\cite{AL14}]\label{prop:carryfree}
Пусть $N-1=\sum_tp_t3^t$ --- уравновешенная запись. Суммы $\sum_tp_t\lambda_{j-t}$ лежат в
$\{-1,0,1\}$ для всех $\lambda\in\Sig$ и $j$ тогда и только тогда, когда среди $p_t$ не больше
одной $+1$ и не больше одной $-1$. В этом случае $\delta_j=\sum_tp_t\lambda_{j-t}$, и
\begin{enumerate}
\item $C(1,3^c+1)=\{\lambda:\ \lambda_j\lambda_{j-c}=0\ \forall j\}$, $F(3^c+1)=\lth$;
\item $C(1,3^{2a}-3^a+1)$: на каждой цепочке $x_t=\lambda_{ta+r}$ после смены значения следующий
элемент равен текущему; $F=\lth$;
\item (\st{Н}) при $c\ge2$: $\lambda\in C(1,3^c-2)$ $\iff$ любые две смены значения отстоят не
меньше чем на $c$; $F(3^c-2)=\log_3\rho_c$, где $\rho_c$ --- наибольший корень $x^c=x^{c-1}+1$.
\end{enumerate}

[\NEW, условная редукция]\label{thm:M0}
\begin{enumerate}
\item[(i)] Если $W_3(L)=o(9^L)$, то верна гипотеза~\ref{conj:metric}.
\item[(ii)] Если $V_4(c)=O((13.5-\eps)^c)$, то $W_3(L)=O((9-\eps')^L)$.
\end{enumerate}

[\NEW, метрическая теория; \S\ref{sec:metric}]\label{thm:intro-metric}
\begin{enumerate}
\item[(a)] Мера Хаара множества $\{b\in\Zt^\times: E_b\ne\{0\}\}$ равна $0$ или полна; $\dimH E_b$ почти всюду постоянна.
\item[(b)] Для почти всех $b$: $\dimH E_b\le0.127$.
\item[(c)] Если $V_4(c):=\sum_{t\in(\Z/3^c)^\times}\bigl|\sum_{x\in\Sig_c}\chi_t(1+3x)\bigr|^4=O((13.5-\eps)^c)$, то $E_b=\{0\}$ для почти всех $b$.
\end{enumerate}

[монотонность и супермодулярность $H$]\label{lem:Hprops}
\begin{enumerate}
\item[(i)] $M\subset M'\Rightarrow H_n(M')\le H_n(M)$.
\item[(ii)] $H_n(X)+H_n(Y)\le H_n(X\cup Y)+H_n(X\cap Y)$.
\item[(iii)] Если $0\in M$, то $H_n(M)=H_{n-1}(\sigma M)$, где $\sigma M:=\{t-1:t\in M,t\ge1\}$. Если $0\notin M$, то $H_n(M)=H_{n-1}(\sigma M)+H_{n-1}(\sigma M\cup(D-1))$.
\end{enumerate}

\label{lem:reductions}
\begin{enumerate}
\item[(i)] Для $\lambda\ne0$ и $k\ge0$: $3^k\lambda\in\Sig\iff\lambda\in\Sig$. Если $\lambda=3^{v}\lambda'$ с единицей $\lambda'$, то $\lambda\in\Sig\iff\lambda'\in A$.
\item[(ii)] Если $u\equiv2\pmod3$, то $\Sig\cap u^{-1}\Sig=\{0\}$.
\item[(iii)] Пусть $b\equiv2\pmod3$ и $\lambda\ne0$. Тогда все $n$, для которых $b^n\lambda\in\Sig$, имеют одинаковую чётность.
\end{enumerate}

[\CAP]\label{thm:CAP}
Для
\[
N\in\mathcal N_0=\bigl\{6,7,12,13,15,16,19,21,24,30,33,-5,-6,\tfrac65,\tfrac74,\tfrac37\bigr\}
\]
имеем $\Haar(B(N))=0$. Следовательно, для Haar-почти всех $b\in\Zt^\times$ ни одна $\lambda\ne0$ не имеет трёх визитов $n_0,n_1,n_2$ с $n_2-n_0=N(n_1-n_0)$.

[\NEW]\label{prop:locality}
Зафиксируем $h\ge0$ и различные нечётные $k_1<\dots<k_K$.
\begin{enumerate}
\item[(a)] Существуют показатели $e_1,\dots,e_K$ с $4^{e_j}\equiv1+3^{k_j}\pmod{3^{k_j+h+1}}$.
\item[(b)] $\dimH C(1,1+3^{k_1},\dots,1+3^{k_K})\ge\frac12\log_32$.
\end{enumerate}
Следовательно, никакая оценка $\dimH C(1,u_1,\dots,u_K)\le\mathcal B$, справедливая для \emph{всех} единиц с заданными вычетами $u_j\bmod3^{g(u_j)+h+1}$, не может дать $\mathcal B<\frac12\log_32$ на конфигурациях степеней четвёрки.
